requirement:
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://schemas.casa.kz/credit-history/snapshot-1.0.0.json",
  "title": "CASA Credit History Snapshot",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version", "snapshot_id", "tenant_id", "case_id",
    "participant_id", "created_at", "source", "verification",
    "current_debt_profile", "historical_credit_profile", "quality",
    "engines", "snapshot_hash"
  ],
  "properties": {
    "schema_version": {"const": "casa.credit_history_snapshot/1.0.0"},
    "snapshot_id": {"type": "string", "pattern": "^chs_[A-Za-z0-9_-]+$"},
    "tenant_id": {"type": "string"},
    "case_id": {"type": "string"},
    "participant_id": {"type": "string"},
    "created_at": {"type": "string", "format": "date-time"},
    "created_by": {"type": "object"},
    "source": {"$ref": "#/$defs/source"},
    "verification": {"$ref": "#/$defs/verification"},
    "source_facts": {"type": "object"},
    "lineages": {"type": "array", "items": {"type": "object"}},
    "current_debt_profile": {"$ref": "#/$defs/currentDebtProfile"},
    "historical_credit_profile": {"$ref": "#/$defs/historicalProfile"},
    "quality": {"$ref": "#/$defs/quality"},
    "engines": {"type": "object"},
    "snapshot_hash": {"type": "string", "pattern": "^[0-9a-f]{64}$"}
  },
  "$defs": {
    "money": {
      "type": "object",
      "additionalProperties": false,
      "required": ["amount", "currency"],
      "properties": {
        "amount": {"type": "string", "pattern": "^-?[0-9]+(\\.[0-9]{1,8})?$"},
        "currency": {"type": "string", "pattern": "^[A-Z]{3}$"}
      }
    },
    "moneyMap": {
      "type": "object",
      "propertyNames": {"pattern": "^[A-Z]{3}$"},
      "additionalProperties": {"type": "string", "pattern": "^[0-9]+(\\.[0-9]{1,8})?$"}
    },
    "metric": {
      "oneOf": [
        {"type": ["integer", "number", "string"]},
        {
          "type": "object",
          "additionalProperties": false,
          "required": ["status", "reason_code"],
          "properties": {
            "status": {"const": "UNKNOWN"},
            "reason_code": {"type": "string"}
          }
        }
      ]
    },
    "source": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "document_version_id", "sha256", "bureau", "report_kind",
        "report_generated_at", "pages_actual", "template_id", "template_version"
      ],
      "properties": {
        "document_version_id": {"type": "string"},
        "sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
        "bureau": {"enum": ["FCB", "SCB", "UNKNOWN"]},
        "report_kind": {"enum": ["FULL_PERSONAL", "PERSONAL", "PARTIAL", "UNKNOWN"]},
        "report_id_masked": {"type": "string"},
        "report_generated_at": {"type": "string", "format": "date-time"},
        "report_time_zone_status": {"enum": ["EXPLICIT", "ASSUMED", "UNKNOWN"]},
        "pages_declared": {"type": ["integer", "null"], "minimum": 1},
        "pages_actual": {"type": "integer", "minimum": 1},
        "template_id": {"type": "string"},
        "template_version": {"type": "string"}
      }
    },
    "verification": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "file_integrity_status", "authenticity_status",
        "extraction_quality_status", "reconciliation_status",
        "manual_review_status", "consent_evidence_id"
      ],
      "properties": {
        "file_integrity_status": {"enum": ["VALID", "CORRUPT", "HASH_MISMATCH", "UNREADABLE"]},
        "authenticity_status": {"enum": [
          "VERIFIED_SIGNATURE", "VERIFIED_BUREAU_MANUAL",
          "UNVERIFIED_FLATTENED_PDF", "UNVERIFIED_SCAN",
          "FAILED", "UNKNOWN"
        ]},
        "extraction_quality_status": {"enum": ["PASS", "PASS_WITH_REVIEW", "NEEDS_REVIEW", "FAILED"]},
        "reconciliation_status": {"enum": ["PASS", "PASS_WITH_REVIEW", "FAIL", "UNKNOWN"]},
        "manual_review_status": {"enum": ["NOT_STARTED", "IN_PROGRESS", "COMPLETED", "WAIVED_BY_POLICY"]},
        "consent_evidence_id": {"type": "string"}
      }
    },
    "currentDebtProfile": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "active_obligation_count", "total_outstanding_by_currency",
        "total_reported_payment_by_currency", "active_current_delinquency_count",
        "max_current_dpd", "active_card_count", "active_mfo_count"
      ],
      "properties": {
        "active_obligation_count": {"$ref": "#/$defs/metric"},
        "total_outstanding_by_currency": {"$ref": "#/$defs/moneyMap"},
        "total_reported_payment_by_currency": {"$ref": "#/$defs/moneyMap"},
        "active_current_delinquency_count": {"$ref": "#/$defs/metric"},
        "max_current_dpd": {"$ref": "#/$defs/metric"},
        "active_card_count": {"$ref": "#/$defs/metric"},
        "active_mfo_count": {"$ref": "#/$defs/metric"},
        "card_limits_by_currency": {"$ref": "#/$defs/moneyMap"},
        "card_utilized_by_currency": {"$ref": "#/$defs/moneyMap"},
        "active_guarantee_count": {"$ref": "#/$defs/metric"},
        "unknown_current_amount_count": {"$ref": "#/$defs/metric"},
        "stale_active_record_count": {"$ref": "#/$defs/metric"}
      }
    },
    "historicalProfile": {
      "type": "object",
      "required": [
        "source_contract_record_count", "canonical_obligation_count",
        "max_dpd_lifetime", "mfo_source_contract_record_count",
        "application_count_30d", "inquiry_count_30d",
        "inquiry_count_90d", "inquiry_count_180d"
      ],
      "properties": {
        "source_contract_record_count": {"$ref": "#/$defs/metric"},
        "canonical_obligation_count": {"$ref": "#/$defs/metric"},
        "max_dpd_lifetime": {"$ref": "#/$defs/metric"},
        "mfo_source_contract_record_count": {"$ref": "#/$defs/metric"},
        "application_count_30d": {"$ref": "#/$defs/metric"},
        "inquiry_count_30d": {"$ref": "#/$defs/metric"},
        "inquiry_count_90d": {"$ref": "#/$defs/metric"},
        "inquiry_count_180d": {"$ref": "#/$defs/metric"}
      }
    },
    "quality": {
      "type": "object",
      "required": ["blocking_issue_count", "warning_count", "unknown_critical_field_count"],
      "properties": {
        "blocking_issue_count": {"type": "integer", "minimum": 0},
        "warning_count": {"type": "integer", "minimum": 0},
        "unknown_critical_field_count": {"type": "integer", "minimum": 0}
      }
    }
  }
}

