requirement:
{
  "$id": "https://schemas.casa.kz/credit-history/contract-record-1.0.0.json",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "record_id", "document_version_id", "parse_run_id", "section",
    "source_ordinal", "creditor", "contract", "classification",
    "state", "amounts", "delinquency", "evidence_ids", "review_status"
  ],
  "properties": {
    "record_id": {"type": "string"},
    "document_version_id": {"type": "string"},
    "parse_run_id": {"type": "string"},
    "section": {"enum": ["ACTIVE", "CLOSED", "CLOSED_OVER_FIVE_YEARS", "RECALLED", "UNKNOWN"]},
    "source_ordinal": {"type": "integer", "minimum": 1},
    "creditor": {
      "type": "object",
      "required": ["name_raw", "type"],
      "properties": {
        "name_raw": {"type": "string"},
        "name_normalized": {"type": ["string", "null"]},
        "bin_masked": {"type": ["string", "null"]},
        "type": {"enum": ["BANK", "MFO", "CREDIT_PARTNERSHIP", "PAWNSHOP", "COLLECTOR", "OTHER", "UNKNOWN"]}
      }
    },
    "contract": {
      "type": "object",
      "required": ["contract_code_raw"],
      "properties": {
        "contract_code_raw": {"type": ["string", "null"]},
        "agreement_number_raw": {"type": ["string", "null"]},
        "start_date": {"type": ["string", "null"], "format": "date"},
        "end_date": {"type": ["string", "null"], "format": "date"},
        "actual_close_date": {"type": ["string", "null"], "format": "date"}
      }
    },
    "classification": {
      "type": "object",
      "required": ["product_type", "subject_role"],
      "properties": {
        "product_type": {"enum": ["LOAN", "MICROLOAN", "CREDIT_CARD", "CREDIT_LINE", "INSTALLMENT", "MORTGAGE", "OVERDRAFT", "GUARANTEE", "SURETY", "OTHER", "UNKNOWN"]},
        "subject_role": {"enum": ["BORROWER", "CO_BORROWER", "JOINT_BORROWER", "GUARANTOR", "SURETY_PROVIDER", "PLEDGOR", "OTHER", "UNKNOWN"]}
      }
    },
    "state": {
      "type": "object",
      "required": ["phase", "record_as_of"],
      "properties": {
        "phase": {"enum": ["ACTIVE", "CLOSED", "CLOSED_EARLY", "ASSIGNED_OUT", "RECALLED", "UNKNOWN"]},
        "record_as_of": {"type": ["string", "null"], "format": "date"},
        "source_status_raw": {"type": ["string", "null"]},
        "rehabilitation_status_raw": {"type": ["string", "null"]}
      }
    },
    "amounts": {
      "type": "object",
      "properties": {
        "currency": {"type": ["string", "null"], "pattern": "^[A-Z]{3}$"},
        "original_principal": {"type": ["string", "null"]},
        "credit_limit": {"type": ["string", "null"]},
        "outstanding_total_reported": {"type": ["string", "null"]},
        "periodic_payment_reported": {"type": ["string", "null"]},
        "minimum_payment_reported": {"type": ["string", "null"]},
        "components": {"type": "array", "items": {"type": "object"}}
      }
    },
    "delinquency": {
      "type": "object",
      "properties": {
        "current_dpd": {"type": ["integer", "null"], "minimum": 0},
        "max_dpd_lifetime_reported": {"type": ["integer", "null"], "minimum": 0},
        "monthly_observations": {"type": "array", "items": {"type": "object"}}
      }
    },
    "assignment": {"type": ["object", "null"]},
    "related_contract_refs": {"type": "array", "items": {"type": "object"}},
    "evidence_ids": {"type": "array", "minItems": 1, "items": {"type": "string"}},
    "review_status": {"enum": ["EXTRACTED", "NEEDS_REVIEW", "ACCEPTED", "CORRECTED", "REJECTED"]}
  }
}

